327	     *  its person's last statement bound it to (unless it is PENDING, which no statement binds), else its live due;
328	     *  null when that is n/a. */
329	    public BigDecimal figure(String sheetId, Person person, Claim claim) {
330	        if (claim.getSettledDue() != null) return claim.getSettledDue();
331	        if (claim.isBound()) return claim.getStatedDue();
332	        return dueNow(sheetId, person, claim);
