335	    /** What is due on the claim now at the rate in force on the claim's date of its person's grade in
336	     *  force on that date, rounded
337	     *  as the claim's {@link Rounding} decides and at least the sheet's floor (a correction has no floor); null when no rate of the
338	     *  grade applies by then. */
339	    private BigDecimal dueNow(String sheetId, Person person, Claim claim) {
340	        Rate rate = rates.inForce(sheetId, person.gradeOn(claim.getDate()), claim.getDate());
341	        if (rate == null) return null;
342	        BigDecimal due = claim.getAmount().multiply(rate.getPct()).divide(BigDecimal.valueOf(100), 2,
343	                rounding(sheetId, claim));
344	        return claim.isCorrection() ? due : due.max(settings.floor(sheetId));
345	    }
