350	        Claim corrected = claim.isCorrection() && claim.getCorrects() != null
351	                ? claims.findBySheetIdAndPersonIdAndNumber(sheetId, claim.getPersonId(), claim.getCorrects()).orElse(null)
352	                : null;
353	        return Rounding.of(Rounding.dateOf(claim, corrected),
354	                Rounding.policyDate(settings.policyDate(sheetId), sheets.today(sheetId)));
